mapper.update:
update blossom_ai_device_token
   set revoked_time = now(), upd_time = now()
 where id = #{id} and user_id = #{userId}

mapper.select:
select id, pid, name, tags, words, version, revision, cre_time, upd_time
  from blossom_article
 where user_id = #{userId}
and id < #{cursor}
and pid = #{folderId}
and upd_time > #{updatedAfter}
 order by id desc
 limit #{limit}

select id, pid, name, tags, words, version, revision, markdown, cre_time, upd_time
  from blossom_article
 where user_id = #{userId}
   and (`name` like concat('%', #{query}, '%')
        or tags like concat('%', #{query}, '%')
        or markdown like concat('%', #{query}, '%'))
and id < #{cursor}
 order by id desc
 limit #{limit}

select ifnull(max(sort), 0)
  from blossom_article
 where pid = #{folderId} and user_id = #{userId}

mapper.update:
update blossom_ai_idempotency
   set resource_id = #{resourceId}
 where id = #{id} and token_id = #{tokenId}

mapper.delete:
delete from blossom_ai_idempotency
 where token_id = #{tokenId} and operation = #{operation} and idempotency_key = #{idempotencyKey}
   and cre_time < date_sub(now(), interval 24 hour)
